package task

import "testing"

func TestAllowedIncludesLimit(t *testing.T) {
	for _, test := range []struct {
		count, limit int
		want         bool
	}{{4, 5, true}, {5, 5, true}, {6, 5, false}} {
		if got := Allowed(test.count, test.limit); got != test.want {
			t.Errorf("Allowed(%d, %d) = %v, want %v", test.count, test.limit, got, test.want)
		}
	}
}

